1	/* One native proof, always scoped to a live ID/generation and engine. */
2	typedef struct {
3	    GtkWidget *source;
4	    guint64 publication,lease,epoch,view_id,view_generation;
5	    gint64 captured;
6	    double px,py,x,y;
7	    guint key;
8	    gboolean pointer,pressed,available,released;
9	} ContextProof;
10	static ContextProof context_proof;
11	static guint held_context_keys;
12	static guint64 context_epoch;
13	static guint64 context_anchor_view,context_anchor_generation,context_anchor_epoch;
14	static ContextKeySource popup_context_keys;
15	static JsonNode *terminal_navigation;
16	static ContextProof terminal_proof;
17	static void terminal_cancel(void) {
18	    if(terminal_navigation)json_node_unref(terminal_navigation);
19	    terminal_navigation=NULL;
20	}
21	static void terminal_release(GtkWidget *widget,guint key);
22	static gboolean shared_native_escape_press(GtkWidget *widget);
23	static void shared_context_cancel(void) {
24	    terminal_cancel();
