71	    double zoom=webkit_web_view_get_zoom_level(WEBKIT_WEB_VIEW(widget));
72	    if (zoom<=0) return FALSE;
73	    if (qa_exit && (event->type==GDK_KEY_PRESS || event->type==GDK_KEY_RELEASE)) {
74	        GdkEventKey *key=(GdkEventKey *)event;
75	        g_print("context-key-event: type=%u hardware=%u key=%u state=%u time=%u send=%u view=%" G_GUINT64_FORMAT " generation=%" G_GUINT64_FORMAT " popup=%u engine=%p window=%p device=%p held=%u\n",
76	            (guint)key->type,key->hardware_keycode,key->keyval,key->state,key->time,(guint)key->send_event,
77	            origin->id,origin->generation,(guint)(widget==GTK_WIDGET(popup_view)),(void *)widget,(void *)key->window,
