80	    }
81	    guint forbidden=GDK_CONTROL_MASK|GDK_MOD1_MASK|GDK_SUPER_MASK|GDK_META_MASK;
82	    if (event->type==GDK_BUTTON_PRESS) {
83	        GdkEventButton *button=(GdkEventButton *)event;
84	        context_proof=(ContextProof){.source=widget,.epoch=context_epoch,.publication=surface_gate.publication,.lease=surface_gate.lease,
85	            .captured=g_get_monotonic_time(),.pointer=TRUE,.px=button->x/zoom,.py=button->y/zoom};
86	        context_proof.pressed=button->button==3 && !(button->state&(GDK_BUTTON1_MASK|GDK_BUTTON2_MASK|GDK_BUTTON4_MASK|GDK_BUTTON5_MASK));
87	    } else if (event->type==GDK_MOTION_NOTIFY && context_proof.pressed) {
88	        GdkEventMotion *motion=(GdkEventMotion *)event;
89	        double dx=motion->x/zoom-context_proof.px,dy=motion->y/zoom-context_proof.py;
90	        if (widget!=context_proof.source || dx*dx+dy*dy>25) context_proof.pressed=FALSE;
91	    } else if (event->type==GDK_BUTTON_RELEASE) {
92	        GdkEventButton *button=(GdkEventButton *)event;
93	        double dx=button->x/zoom-context_proof.px,dy=button->y/zoom-context_proof.py;
94	        gboolean matched=context_proof.pressed && context_proof.source==widget && button->button==3
95	            && !(button->state&(GDK_BUTTON1_MASK|GDK_BUTTON2_MASK|GDK_BUTTON4_MASK|GDK_BUTTON5_MASK))
96	            && context_proof.publication==surface_gate.publication && context_proof.lease==surface_gate.lease && dx*dx+dy*dy<=25;
97	        context_proof.pressed=FALSE;context_proof.available=matched;
98	        context_proof.x=button->x/zoom;context_proof.y=button->y/zoom;context_proof.captured=g_get_monotonic_time();
99	    } else if (event->type==GDK_KEY_PRESS) {
100	        GdkEventKey *key=(GdkEventKey *)event;
101	        gboolean context=key->keyval==GDK_KEY_Menu || (key->keyval==GDK_KEY_F10 && (key->state&GDK_SHIFT_MASK));
102	        gboolean navigation=key->keyval==GDK_KEY_Escape || key->keyval==GDK_KEY_Up || key->keyval==GDK_KEY_Down
103	            || key->keyval==GDK_KEY_Home || key->keyval==GDK_KEY_End || key->keyval==GDK_KEY_Return;
104	        guint bit=context_key_bit(key->keyval);
105	        gboolean fresh=!(held_context_keys&bit);
106	        held_context_keys|=bit;
107	        context_proof=(ContextProof){.source=widget,.epoch=context_epoch,.publication=surface_gate.publication,.lease=surface_gate.lease,
108	            .captured=g_get_monotonic_time(),.key=key->keyval,.available=(context||navigation)&&fresh&&!(key->state&forbidden)};
109	        if(qa_exit){g_print("context-key-report: key=%u state=%u hardware=%u time=%u fresh=%d available=%d popup=%d\n",key->keyval,key->state,key->hardware_keycode,key->time,fresh,context_proof.available,widget==GTK_WIDGET(popup_view));fflush(stdout);}
110	    } else if (event->type==GDK_KEY_RELEASE) {
111	        guint released=((GdkEventKey *)event)->keyval;
112	        gboolean was_held=(held_context_keys&context_key_bit(released))!=0;
113	        if(was_held && context_proof.source==widget && !context_proof.pointer && context_proof.key==released)
