124	}
125	typedef struct {JsonNode *message;ContextProof proof;gboolean popup;GObject *engine;} ContextCheck;
126	static gboolean context_identity_current(const ContextProof *proof,gboolean popup) {
127	    OutputView *origin=context_engine(proof->source);
128	    gint64 age=g_get_monotonic_time()-proof->captured;
129	    return !shutting_down && context_epoch!=G_MAXUINT64 && origin && origin->id==proof->view_id && origin->generation==proof->view_generation
130	        && proof->epoch==context_epoch && proof->publication==surface_gate.publication && proof->lease==surface_gate.lease
131	        && proof->captured>0 && age>=0 && age<=500000
132	        && ((popup && proof->source==GTK_WIDGET(popup_view) && origin==popup_owner)
133	            || (!popup && proof->source==GTK_WIDGET(origin->engine)));
134	}
135	/* Escape dismisses a native grabbed menu even before its renderer acknowledgement.
136	 * It carries no window effect. All other navigation retains full render readiness. */
137	static gboolean context_current(const ContextProof *proof,gboolean popup) {
138	    return context_identity_current(proof,popup) && (!popup || surface_popup_ready());
139	}
140	static gboolean context_terminal_current(const ContextProof *proof) {
141	    gboolean dismissal_ready=proof->key==GDK_KEY_Escape && popup_active && grab_ready && keyboard_ready
142	        && configured_lease==surface_gate.lease && surface_gate.lease>surface_gate.closed;
143	    return context_identity_current(proof,TRUE) && (dismissal_ready || surface_popup_ready());
144	}
145	/* Terminal navigation must retain the popup until the admitted physical
146	 * release. Otherwise teardown loses that release and leaves repeat guards held.
147	 * The original proof deadline/scope/publication are never renewed here. */
148	static gboolean terminal_store(JsonNode *message,const ContextProof *proof) {
149	    gboolean held=(held_context_keys&context_key_bit(proof->key))!=0;
150	    if(terminal_navigation || !context_terminal_current(proof) ||
151	       (proof->key!=GDK_KEY_Escape && proof->key!=GDK_KEY_Return) ||
152	       (held==proof->released))return FALSE;
153	    terminal_navigation=json_node_copy(message);terminal_proof=*proof;return TRUE;
154	}
155	/* An effectless Escape intent belongs to the admitted physical press, not a
156	 * delayed DOM publication. Keep its immutable stamp and original deadline;
157	 * the existing matched physical release is the only forwarding path. */
158	static gboolean shared_native_escape_press(GtkWidget *widget) {
159	    const ContextProof *proof=&context_proof;
160	    if(!surface_snapshot || !JSON_NODE_HOLDS_OBJECT(surface_snapshot) ||
161	       !proof->available || proof->pointer || proof->released ||
162	       proof->key!=GDK_KEY_Escape || proof->source!=widget ||
163	       !(held_context_keys&context_key_bit(GDK_KEY_Escape)))return FALSE;
164	    JsonObject *snapshot=json_node_get_object(surface_snapshot);guint64 publication,lease;
165	    if(g_strcmp0(json_object_get_string_member(snapshot,"mode"),"menu")!=0 ||
166	       !surface_uint(json_object_get_member(snapshot,"publication"),&publication) || publication!=proof->publication ||
167	       !surface_uint(json_object_get_member(snapshot,"lease"),&lease) || lease!=proof->lease)return FALSE;
168	    JsonObject *object=json_object_new();
169	    json_object_set_int_member(object,"surfaceProtocol",2);
170	    json_object_set_string_member(object,"kind","surface-menu-navigation");
171	    json_object_set_string_member(object,"surface","popup");
172	    g_autofree char *stamp=g_strdup_printf("%" G_GUINT64_FORMAT,proof->publication);
173	    g_autofree char *token=g_strdup_printf("%" G_GUINT64_FORMAT,proof->lease);
174	    json_object_set_string_member(object,"publication",stamp);
175	    json_object_set_string_member(object,"lease",token);
176	    json_object_set_string_member(object,"key","Escape");
