183	}
184	static JsonNode *terminal_take(GtkWidget *widget,guint key) {
185	    if(!terminal_navigation || terminal_proof.source!=widget || terminal_proof.key!=key)return NULL;
186	    JsonNode *message=terminal_navigation;terminal_navigation=NULL;
187	    if(!context_terminal_current(&terminal_proof) || (held_context_keys&context_key_bit(key))) {
188	        json_node_unref(message);return NULL;
189	    }
