197	}
198	static gboolean context_finish_allowed(const ContextProof *proof,gboolean popup,GObject *object,gboolean dom_verified) {
199	    return dom_verified && object==G_OBJECT(proof->source) && context_current(proof,popup);
200	}
201	static void context_checked(GObject *object,GAsyncResult *result,gpointer data) {
202	    ContextCheck *check=data;GError *error=NULL;
203	    JSCValue *value=webkit_web_view_evaluate_javascript_finish(WEBKIT_WEB_VIEW(object),result,&error);
204	    gboolean dom_verified=!error && value && jsc_value_is_boolean(value) && jsc_value_to_boolean(value);
205	    gboolean admitted=context_finish_allowed(&check->proof,check->popup,object,dom_verified);
206	    if(admitted) {
207	        if(check->proof.pointer && !check->popup) {
208	            double zoom=webkit_web_view_get_zoom_level(WEBKIT_WEB_VIEW(check->proof.source));
209	            context_anchor_view=check->proof.view_id;context_anchor_generation=check->proof.view_generation;context_anchor_epoch=context_epoch;
210	            context_anchor=(GdkRectangle){(int)(check->proof.x*zoom),(int)(check->proof.y*zoom),1,1};has_context_anchor=TRUE;
211	        } else has_context_anchor=FALSE;
