213	        g_print("surface-context-admitted: view=%" G_GUINT64_FORMAT " generation=%" G_GUINT64_FORMAT " origin=%s trigger=%s publication=%" G_GUINT64_FORMAT " lease=%" G_GUINT64_FORMAT "\n",
