229	        || json_node_get_value_type(json_object_get_member(o,"surfaceProtocol"))!=G_TYPE_INT64 || json_object_get_int_member(o,"surfaceProtocol")!=2
230	        || !surface_text(json_object_get_member(o,"kind"),32,FALSE) || !g_str_equal(json_object_get_string_member(o,"kind"),"surface-context")
231	        || !surface_text(json_object_get_member(o,"surface"),16,FALSE) || !g_str_equal(json_object_get_string_member(o,"surface"),popup?"popup":"bar")
232	        || !surface_uint(json_object_get_member(o,"publication"),&publication) || publication!=surface_gate.publication
233	        || !surface_uint(json_object_get_member(o,"lease"),&lease) || lease!=surface_gate.lease
234	        || !surface_text(json_object_get_member(o,"id"),512,FALSE) || !surface_text(json_object_get_member(o,"trigger"),16,FALSE)
235	        || json_node_get_value_type(json_object_get_member(o,"x"))!=G_TYPE_INT64 || json_node_get_value_type(json_object_get_member(o,"y"))!=G_TYPE_INT64) return FALSE;
236	    const char *trigger=json_object_get_string_member(o,"trigger");
237	    gboolean pointer=g_str_equal(trigger,"pointer"),keyboard=g_str_equal(trigger,"keyboard");
238	    if ((!pointer&&!keyboard) || !context_proof.available || context_proof.pointer!=pointer || !context_current(&context_proof,popup)
239	        || (keyboard && context_proof.key!=GDK_KEY_Menu && context_proof.key!=GDK_KEY_F10)) return FALSE;
240	    gint64 x=json_object_get_int_member(o,"x"),y=json_object_get_int_member(o,"y");
241	    double dx=(double)x-context_proof.x,dy=(double)y-context_proof.y;
242	    if (pointer && (dx*dx+dy*dy>2 || x<0 || y<0)) return FALSE;
243	    if (keyboard && (x!=0 || y!=0)) return FALSE;
244	    JsonArray *controls=json_object_get_array_member(json_node_get_object(surface_snapshot),popup?"popup":"bar");
245	    gboolean found=FALSE;
246	    for (guint i=0;i<json_array_get_length(controls);i++) {
247	        JsonObject *control=json_array_get_object_element(controls,i);
248	        if (g_str_equal(json_object_get_string_member(control,"id"),json_object_get_string_member(o,"id")) && json_object_get_boolean_member(control,"enabled")) found=TRUE;
249	    }
250	    if (!found) return FALSE;
