252	}
253	static gboolean context_consume(const ContextProof *proof,gboolean popup) {
254	    if(!context_proof.available || !context_current(proof,popup) || proof->source!=context_proof.source || proof->epoch!=context_proof.epoch) return FALSE;
255	    context_proof.available=FALSE;return TRUE;
256	}
257	static gboolean shared_context_receive(WebKitUserContentManager *manager,JsonNode *root) {
258	    ContextProof proof;gboolean popup;
259	    if(!context_admit(manager,root,&proof,&popup) || !context_consume(&proof,popup)) return FALSE;
260	    ContextCheck *check=g_new0(ContextCheck,1);check->message=json_node_copy(root);check->proof=proof;check->popup=popup;check->engine=g_object_ref(G_OBJECT(proof.source));
261	    context_proof.available=FALSE;
262	    g_autofree char *wire=json_to_string(root,FALSE);
263	    g_autofree char *script=NULL;
264	    if (proof.pointer) script=g_strdup_printf("(()=>{const c=%s,n=document.querySelector('.surface-%s'),hit=(x,y)=>document.elementFromPoint(x,y)?.closest('[data-surface-control]');if(!n||n.dataset.publication!==c.publication||n.dataset.lease!==c.lease)return false;const a=hit(%.17g,%.17g),b=hit(c.x,c.y);return !!a&&!!b&&n.contains(a)&&n.contains(b)&&!a.disabled&&!b.disabled&&a.dataset.surfaceControl===c.id&&b.dataset.surfaceControl===c.id;})()",wire,popup?"popup":"bar",check->proof.px,check->proof.py);
