268	}
269	static gboolean shared_navigation_key(guint key,const char *name) {
270	    const char *names[]={"Escape","ArrowUp","ArrowDown","Home","End","Enter","Close"};
271	    const guint keys[]={GDK_KEY_Escape,GDK_KEY_Up,GDK_KEY_Down,GDK_KEY_Home,GDK_KEY_End,GDK_KEY_Return,GDK_KEY_Return};
272	    for(guint i=0;i<G_N_ELEMENTS(names);i++)if(g_strcmp0(name,names[i])==0 && key==keys[i])return TRUE;
273	    return FALSE;
274	}
275	static gboolean shared_navigation_receive(WebKitUserContentManager *manager,JsonNode *root) {
276	    if (manager!=popup_manager || !surface_snapshot || !JSON_NODE_HOLDS_OBJECT(root)) return FALSE;
277	    if (!g_str_equal(json_object_get_string_member(json_node_get_object(surface_snapshot),"mode"),"menu")) return FALSE;
278	    JsonObject *o=json_node_get_object(root);guint64 publication,lease;
279	    const char *const fields[]={"surfaceProtocol","kind","surface","publication","lease","key"};
280	    if (!surface_fields(o,fields,6) || json_node_get_value_type(json_object_get_member(o,"surfaceProtocol"))!=G_TYPE_INT64 || json_object_get_int_member(o,"surfaceProtocol")!=2
281	        || !surface_text(json_object_get_member(o,"kind"),32,FALSE) || !g_str_equal(json_object_get_string_member(o,"kind"),"surface-menu-navigation")
282	        || !surface_text(json_object_get_member(o,"surface"),16,FALSE) || !g_str_equal(json_object_get_string_member(o,"surface"),"popup")
283	        || !surface_uint(json_object_get_member(o,"publication"),&publication) || publication!=surface_gate.publication
284	        || !surface_uint(json_object_get_member(o,"lease"),&lease) || lease!=surface_gate.lease || !surface_text(json_object_get_member(o,"key"),16,FALSE)
285	        || !context_proof.available || context_proof.pointer || !context_terminal_current(&context_proof)) return FALSE;
286	    if(!shared_navigation_key(context_proof.key,json_object_get_string_member(o,"key")))return FALSE;
287	    if(context_proof.key==GDK_KEY_Escape || context_proof.key==GDK_KEY_Return) {
