293	    }
294	    context_proof.available=FALSE;shared_context_forward(popup_owner,root,TRUE);return TRUE;
295	}
296	
297	static gboolean shared_anchor_for(const OutputView *owner,JsonNode *frame) {
298	    return owner && owner->active && has_context_anchor && context_anchor_epoch==context_epoch
299	        && owner->id==context_anchor_view && owner->generation==context_anchor_generation
300	        && frame && JSON_NODE_HOLDS_OBJECT(frame)
301	        && g_strcmp0(json_object_get_string_member(json_node_get_object(frame),"mode"),"menu")==0;
302	}
